from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        INF = 10**18
        half = n // 2

        dp = [[INF] * 3 for _ in range(3)]

        for left_color in range(3):
            for right_color in range(3):
                if left_color != right_color:
                    dp[left_color][right_color] = cost[0][left_color] + cost[n - 1][right_color]

        for i in range(1, half):
            new_dp = [[INF] * 3 for _ in range(3)]

            for prev_left in range(3):
                for prev_right in range(3):
                    if dp[prev_left][prev_right] == INF:
                        continue

                    for left_color in range(3):
                        if left_color == prev_left:
                            continue

                        for right_color in range(3):
                            if right_color == prev_right or right_color == left_color:
                                continue

                            new_dp[left_color][right_color] = min(
                                new_dp[left_color][right_color],
                                dp[prev_left][prev_right]
                                + cost[i][left_color]
                                + cost[n - 1 - i][right_color],
                            )

            dp = new_dp

        return min(min(row) for row in dp)
